<?php if (!defined('BASEPATH')) exit('No direct script access allowed');class workinprogressmodel extends CI_Model {    function getExtraDetailsOfWip($ArrIds,$VarCompanyId='') {        if(is_array($ArrIds) && count($ArrIds) > 0) {            $VarIds      = implode(',', $ArrIds);            $VarSql      = "SELECT referenceid,jsondatagrid FROM " . ORDERENTRY_DELIVERYSCHEDULESIXTHTBL . " WHERE referenceid IN ($VarIds) AND companyid = $VarCompanyId";            $ArrResAll   = $this->db->query($VarSql)->result();            //echo '<pre>'; print_r($ArrResAll); die('');            $ArrFinalRes = array();            foreach ($ArrResAll as $key => $arrRe) {                $ArrJsonDecoded = json_decode($arrRe->jsondatagrid,true);                if(!empty($ArrJsonDecoded)) {                    //echo '<pre>'; print_r($ArrJsonDecoded);                    foreach ($ArrJsonDecoded as $cols) {                        $ArrFinalRes['pono'][$arrRe->referenceid][] = $cols[3];                        $ArrFinalRes['poq'][$arrRe->referenceid][] = $cols[4];                        $ArrFinalRes['shipdate'][$arrRe->referenceid][] = empty($cols[7]) ? '-' : date('d-m-Y', strtotime($cols[7]));                    }                }            }            //[["2020-05-05 00:00:00","2020-05-05 00:00:00","PO number 11","combo 1","2000","Pcs.","Air",            //"2020-05-05 00:00:00","2020-05-05 00:00:00","2020-05-05 00:00:00","Port of Kochi","INDIA","Port of Kochi","INDIA"],["2020-05-06 00:00:00","2020-05-06 00:00:00","PO number 2","combo 11","2000","Pcs.","Air","2020-05-06 00:00:00","2020-05-06 00:00:00","2020-05-06 00:00:00","Port of Kochi","INDIA","Port of Kochi","INDIA"]]            //[["2020-04-20 00:00:00","2020-04-21 00:00:00","PO-230","Combo - 1","50","Set","Air","2020-05-20 00:00:00","2020-05-19 00:00:00","2020-05-21 00:00:00","Port of Kochi","INDIA","Port of Rotterdam","NETHERLANDS"],["2020-04-21 00:00:00","2020-04-22 00:00:00","PO-231","Combo - 1","50","Set","Air","2020-05-26 00:00:00","2020-05-25 00:00:00","2020-05-26 00:00:00","Port of Tuticorin","INDIA","Port of Antwerp ","GERMANY"],["2020-04-22 00:00:00","2020-04-23 00:00:00","PO-230","Combo - 2","50","Set","Air","2020-05-20 00:00:00","2020-05-19 00:00:00","2020-05-21 00:00:00","Port of Kochi","INDIA","Port of Rotterdam","NETHERLANDS"],["2020-04-23 00:00:00","2020-04-24 00:00:00","PO-231","Combo - 2","50","Set","Air","2020-05-26 00:00:00","2020-05-25 00:00:00","2020-05-26 00:00:00","Port of Tuticorin","INDIA","Port of Antwerp ","GERMANY"]]            return $ArrFinalRes;        }        elseif (!empty($ArrIds)) {            $VarSql      = "SELECT referenceid,jsondatagrid FROM " . ORDERENTRY_DELIVERYSCHEDULESIXTHTBL . " WHERE referenceid = '$ArrIds' AND companyid = '$VarCompanyId' ";            $ArrRes      = $this->db->query($VarSql)->result();            $ArrFinalRes = array();            foreach ($ArrRes as $key => $arrRe) {                $ArrJsonDecoded = json_decode($arrRe->jsondatagrid,true);                if(!empty($ArrJsonDecoded)) {                    foreach ($ArrJsonDecoded as $cols) {                        $ArrFinalRes['pono'][$arrRe->referenceid][] = $cols[2];                        $ArrFinalRes['poq'][$arrRe->referenceid][] = $cols[4];                        $ArrFinalRes['shipdate'][$arrRe->referenceid][] = empty($cols[7]) ? '-' : date('d-m-Y', strtotime($cols[7]));                    }                }            }            return $ArrFinalRes;        }    }    public function getPonumberStatus($ArrIds,$VarCompanyId) {        if(is_array($ArrIds)) {            if(!empty($ArrIds)) {                $VarIds    = implode(',', $ArrIds);                $VarSql    = "SELECT referenceid,commonstatus,remarks,fullpart,updatedby,dateupdated FROM " . WORKINPROCESSTBL . " AS w WHERE                 w.referenceid IN ($VarIds) AND w.companyid = '$VarCompanyId' order by referenceid DESC";                $ArrAllRes = $this->db->query($VarSql)->result();                if(!empty($ArrAllRes)) {                    foreach ($ArrAllRes as $res) {                        $ArrRes[$res->referenceid]['commonstatus'][] = array($res->commonstatus);                    }                    return $ArrRes;                }            }        }        else {            $VarSql    = "SELECT arrpoids,referenceid,commonstatus,remarks,fullpart,updatedby,dateupdated FROM " . WORKINPROCESSTBL . " AS w WHERE             w.referenceid  = '$ArrIds' AND w.companyid = '$VarCompanyId' order by referenceid DESC";            $ArrAllRes = $this->db->query($VarSql)->result();            foreach ($ArrAllRes as $res) {                $ArrRes[$res->referenceid]['arrpoids'][] = array($res->arrpoids);                $ArrRes[$res->referenceid]['commonstatus'][] = array($res->commonstatus);                $ArrRes[$res->referenceid]['remarks'][] = array($res->remarks);                $ArrRes[$res->referenceid]['fullpart'][] = array($res->fullpart);            }            return $ArrRes;        }    }    public function saveEachPonoStatus($ArrModeofshipment,$ObjModeofshipment,$VarShipmentdate,$VarExfactorydate,$VarLoadingport,$VarDestiport,$VarShipmentstatus,                                       $VarCommonss,$VarFullpart,$VarRemarks,$VarDatetime,$VarReferenceId,$VarCompanyId,$VarUpdatedby) {        foreach ($ArrModeofshipment as $key => $modeofshipment) {            $this->db->where('companyid',$VarCompanyId);            $this->db->where('referenceid',$VarReferenceId);            $this->db->where('ponoid',$key);            $ArrData = array('updatedby'=>$VarUpdatedby,'modeofshipment'=>$ObjModeofshipment,'shipmentdate'=>$VarShipmentdate,'exfactorydate'=>                $VarExfactorydate,'loadingport'=>$VarLoadingport,'destiport'=>$VarDestiport,'eachponostatus'=>$VarShipmentstatus,'datecreated'=>                $VarDatetime,'dateupdated'=>$VarDatetime);            $this->db->update(EACHPONOSTATUSTBL,$ArrData);        }        $ArrPonoIds = array_keys($ArrModeofshipment);        $this->db->where('companyid',$VarCompanyId);        $this->db->where('referenceid',$VarReferenceId);        $this->db->where('arrpoids',implode(',',$ArrPonoIds));        $this->db->update(WORKINPROCESSTBL,array('fullpart'=>$VarFullpart,'remarks'=>$VarRemarks,'commonstatus'=>$VarCommonss));        return true;    }    public function getCommonPonumberData($VarId,$VarCompanyId,$VarPoids) {        $VarSql    = "SELECT arrpoids,referenceid,commonstatus,remarks,fullpart FROM " . WORKINPROCESSTBL . " AS w WHERE w.referenceid  = '$VarId' AND         w.companyid = '$VarCompanyId' AND arrpoids = '$VarPoids' order by referenceid DESC";        return $this->db->query($VarSql)->result();    }    public function getEachPonoStatus($VarId,$VarCompanyId,$ArrPoids=array()) {        $VarIds    = implode(',', $ArrPoids);        $VarSql    = "SELECT referenceid,modeofshipment,shipmentdate,exfactorydate,loadingport,destiport,eachponostatus,dateupdated FROM " . EACHPONOSTATUSTBL . " AS e WHERE e.referenceid  = '$VarId' AND         e.companyid = '$VarCompanyId' AND ponoid IN ($VarIds) order by referenceid DESC";        return $this->db->query($VarSql)->result();    }}